"use strict";(self.webpackChunktcc_docs=self.webpackChunktcc_docs||[]).push([["7162"],{78851(r,n,e){e.r(n),e.d(n,{metadata:()=>t,default:()=>p,frontMatter:()=>i,contentTitle:()=>o,toc:()=>c,assets:()=>d});var t=JSON.parse('{"id":"Perl/scripts/create_www_professores_basic","title":"create_www_professores_basic","description":"Apresenta listagem de professores.","source":"@site/docs/Perl/scripts/create_www_professores_basic.mdx","sourceDirName":"Perl/scripts","slug":"/Perl/scripts/create_www_professores_basic","permalink":"/tcc-docs/docs/Perl/scripts/create_www_professores_basic","draft":false,"unlisted":false,"editUrl":"https://github.com/ruseleredu/tcc-docs/edit/main/docs/Perl/scripts/create_www_professores_basic.mdx","tags":[],"version":"current","lastUpdatedBy":"Adriano Ruseler","lastUpdatedAt":1789150874000,"sidebarPosition":56,"frontMatter":{"id":"create_www_professores_basic","title":"create_www_professores_basic","sidebar_position":56,"description":"Apresenta listagem de professores."},"sidebar":"tutorialSidebar","previous":{"title":"create_www_professores","permalink":"/tcc-docs/docs/Perl/scripts/create_www_professores"},"next":{"title":"delete_bancas_professores","permalink":"/tcc-docs/docs/Perl/scripts/delete_bancas_professores"}}'),a=e(74848),s=e(28453);let i={id:"create_www_professores_basic",title:"create_www_professores_basic",sidebar_position:56,description:"Apresenta listagem de professores."},o="create_www_professores_basic.pl",d={},c=[{value:"Overview",id:"overview",level:2},{value:"Perl Modules",id:"perl-modules",level:2},{value:"Database",id:"database",level:2},{value:"Command-Line Options",id:"command-line-options",level:2},{value:"Example",id:"example",level:3},{value:"Source Code",id:"source-code",level:2}];function l(r){let n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...r.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"create_www_professores_basicpl",children:(0,a.jsx)(n.code,{children:"create_www_professores_basic.pl"})})}),"\n",(0,a.jsx)(n.p,{children:"Apresenta listagem de professores."}),"\n",(0,a.jsx)(n.h2,{id:"overview",children:"Overview"}),"\n",(0,a.jsx)(n.p,{children:"This page was generated automatically from the Perl source file."}),"\n",(0,a.jsx)(n.h2,{id:"perl-modules",children:"Perl Modules"}),"\n",(0,a.jsx)(n.p,{children:"The script uses the following modules:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.code,{children:"DBI"})}),"\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.code,{children:"Getopt::Std"})}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"database",children:"Database"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Database interface:"})," MySQL via Perl DBI"]}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"command-line-options",children:"Command-Line Options"}),"\n",(0,a.jsxs)(n.table,{children:[(0,a.jsx)(n.thead,{children:(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.th,{children:"Option"}),(0,a.jsx)(n.th,{children:"Argument"})]})}),(0,a.jsxs)(n.tbody,{children:[(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:(0,a.jsx)(n.code,{children:"-w"})}),(0,a.jsx)(n.td,{children:"No"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:(0,a.jsx)(n.code,{children:"-h"})}),(0,a.jsx)(n.td,{children:"No"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:(0,a.jsx)(n.code,{children:"-u"})}),(0,a.jsx)(n.td,{children:"Required"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:(0,a.jsx)(n.code,{children:"-p"})}),(0,a.jsx)(n.td,{children:"Required"})]})]})]}),"\n",(0,a.jsx)(n.h3,{id:"example",children:"Example"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-bash",children:"perl create_www_professores_basic.pl -h\n"})}),"\n",(0,a.jsx)(n.h2,{id:"source-code",children:"Source Code"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-perl",children:'#!/usr/bin/perl\r\nuse strict;\r\nuse warnings;\r\nuse DBI;\r\nuse Getopt::Std;\r\n\r\n# -----------------------------------------------------------------------------\r\n# Apresenta listagem de professores.\r\n# -----------------------------------------------------------------------------\r\n$|++;\r\nmy $crlf = "\\n";\r\nmy $aplicativo = $0;\r\n\r\n\r\n# defini\xe7\xe3o para acesso do banco (valores default)\r\nmy $host     = "localhost";\r\nmy $database = "DAELT";\r\nmy $usuario  = "";\r\nmy $senha    = "";\r\n\r\n\r\n# Recupera\xe7\xe3o dos par\xe2metros de entrada (via shell)\r\nmy %opcoes=();\r\ngetopts("whu:p:", \\%opcoes);\r\n\r\n$crlf    = "\\r\\n"     if defined $opcoes{w};\r\n$usuario = $opcoes{u} if defined $opcoes{u};\r\n$senha   = $opcoes{p} if defined $opcoes{p};\r\n\r\nif (defined $opcoes{h})\r\n{\r\n	print STDERR "$aplicativo [-w] [-u <usuario>] [-p <senha>]$crlf";\r\n	exit 0;\r\n}\r\n\r\n\r\n# apresenta\xe7\xe3o do programa\r\nprint STDERR "$aplicativo\\::Apresenta listagem de professores.$crlf";\r\n\r\n\r\n# conex\xe3o com banco de dados\r\nmy ($dbHandle,\r\n    $dbStatement1, $dbStatement2, $dbStatement3,\r\n    $dbStatement4, $dbStatement5, $dbStatement6);\r\nmy @dbLinha;\r\n\r\n$dbHandle = DBI->connect("DBI:mysql:database=$database;host=$host",\r\n                         $usuario, $senha,\r\n                         {PrintError => 0, AutoCommit => 0})\r\n	or die "$aplicativo\\::Falha de conex\xe3o ao banco de dados: $DBI::errstr";\r\n\r\n$dbStatement1 = $dbHandle->prepare(\r\n	"SELECT ID, NOME, EMAIL, EMAIL2 " .\r\n	"FROM DAELT.PROFESSORES " .\r\n	"WHERE ID !=\'0\' AND DATA_FIM IS NULL AND EFETIVO != FALSE " .\r\n	"ORDER BY NOME;");\r\n$dbStatement2 = $dbHandle->prepare(\r\n	"SELECT C.NOME " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_GRUPOS B, DAELT.GRUPOS C " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR AND B.ID_GRUPO = C.ID AND " .\r\n	      "B.DATA_FIM IS NULL " .\r\n	"ORDER BY C.NOME;");\r\n$dbStatement3 = $dbHandle->prepare(\r\n	"SELECT B.INTERESSE " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_INTERESSES B " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR " .\r\n	"ORDER BY B.INTERESSE;");\r\n$dbStatement4 = $dbHandle->prepare(\r\n	"SELECT B.TEMA " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_TEMAS B " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR " .\r\n	"ORDER BY B.TEMA;");\r\n$dbStatement5 = $dbHandle->prepare(\r\n	"SELECT A.NOME, B.ID, B.NOME " .\r\n	"FROM DAELT.GRUPOS A, DAELT.PROFESSORES B " .\r\n	"WHERE A.ID_LIDER = B.ID AND A.ID_LIDER != \'0\';");\r\n$dbStatement6 = $dbHandle->prepare(\r\n	"SELECT ID, NOME, EMAIL, EMAIL2 " .\r\n	"FROM DAELT.PROFESSORES " .\r\n	"WHERE ID !=\'0\' AND DATA_FIM IS NULL AND EFETIVO != TRUE " .\r\n	"ORDER BY NOME;");\r\n\r\n\r\n\r\n# impress\xe3o do pre\xe2mbulo (conforme p\xe1gina)\r\nprint <<PREAMBULO_PAGINA;\r\n<!DOCTYPE html>\r\n<html lang="pt-BR">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <title>TCC/DAELT/UTFPR - Engenharia</title>\r\n    <base href="https://nupet.daelt.ct.utfpr.edu.br/tcc/">\r\n    <link rel="stylesheet" href="https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/css/bootstrap.min.css">\r\n    <link rel="stylesheet" type="text/css" href="css/meus-estilos.css">\r\n<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css">\r\n    <style>\r\n        body {\r\n            font-family: \'Arial\', sans-serif;\r\n            background-color: #f8f9fa;\r\n            color: #333;\r\n        }\r\n        .header {\r\n            padding: 20px 0;\r\n            text-align: center;\r\n        }\r\n\r\n        .title {\r\n            text-align: center;\r\n            margin: 20px 0;\r\n            font-size: 2.5rem;\r\n        }\r\n        .navbar {\r\n            background-color: #002147;\r\n        }\r\n        .navbar-nav .nav-link {\r\n            color: white !important;\r\n        }\r\n        .navbar-nav .nav-link:hover {\r\n            color: white !important;\r\n            background-color:#3b3eff;\r\n        }\r\n        .content {\r\n            margin: 20px;\r\n        }\r\n        .container-content {\r\n            text-align: center;\r\n            position:relative;\r\n            margin: 2vw;\r\n            width:80vw;         \r\n            min-height: 680px;\r\n            \r\n        }\r\n\r\n        .card {\r\n            text-align: left;\r\n            margin-bottom: 20px;\r\n\r\n        }\r\n        .footer {\r\n            text-align: center;\r\n            padding: 20px;\r\n            background-color: #002147;\r\n            color: white;\r\n        }\r\n        .footer a {\r\n            color: #ffcc00;\r\n        }\r\n        .footer a:hover {\r\n            color: #e6b800;\r\n        }\r\n        .accordion {\r\n          background-color: #eee;\r\n          color: #444;\r\n          cursor: pointer;\r\n          padding: 18px;\r\n          width: 100%;\r\n          border: none;\r\n          text-align: left;\r\n          outline: none;\r\n          font-size: 18px;\r\n          transition: 0.4s;\r\n        }\r\n\r\n        .accordion:hover {\r\n          background-color: #ccc;\r\n        }\r\n\r\n        .accordion:after {\r\n          content: \'\\002B\';\r\n          color: #777;\r\n          font-weight: bold;\r\n          float: right;\r\n          margin-left: 5px;\r\n        }\r\n\r\n        .panel {\r\n          padding: 0 18px;\r\n          background-color: white;\r\n          max-height: 0;\r\n          overflow: hidden;\r\n          transition: max-height 0.2s ease-out;\r\n        }\r\n    </style>\r\n\r\n</head>\r\n\r\n<body>\r\n\r\n<div class="header">\r\n    <a href="https://utfpr.curitiba.br/daelt/" class="custom-logo-link" rel="home" aria-current="page"><img width="850" height="227" src="./DAELT-CT \u2013 Departamento Acad\xeamico de Eletrot\xe9cnica_files/cropped-header_utfpr.png" class="custom-logo" alt="DAELT-CT" decoding="async" fetchpriority="high" srcset="https://utfpr-ct-static-content.s3.amazonaws.com/utfpr.curitiba.br/wp-content/uploads/sites/9/2020/08/cropped-header_utfpr.png 850w, https://utfpr-ct-static-content.s3.amazonaws.com/utfpr.curitiba.br/wp-content/uploads/sites/9/2020/08/cropped-header_utfpr-300x80.png 300w, https://utfpr-ct-static-content.s3.amazonaws.com/utfpr.curitiba.br/wp-content/uploads/sites/9/2020/08/cropped-header_utfpr-768x205.png 768w" sizes="(max-width: 850px) 100vw, 850px"></a>                  \r\n</div>\r\n<nav class="navbar navbar-expand-lg navbar-dark">\r\n    <div class="container">\r\n       \r\n        <button class="navbar-toggler" type="button" data-toggle="collapse" data-target="#navbarNav" aria-controls="navbarNav" aria-expanded="false" aria-label="Toggle navigation">\r\n            <span class="navbar-toggler-icon"></span>\r\n        </button>\r\n    \r\n        <div class="collapse navbar-collapse" id="navbarNav">\r\n            <a class="active" href="https://nupet.daelt.ct.utfpr.edu.br/tcc/engenharia/index.html"><i class="fa fa-fw fa-home"></i><b>TCC</b></a>\r\n            <ul class="navbar-nav mx-auto">\r\n                <li class="nav-item"><a class="nav-link" href="engenharia/metodologia.html"><b>Metodologia Aplicada ao TCC </b></a></li>\r\n                <li class="nav-item"><a class="nav-link" href="engenharia/tcc1.html"><b>Trabalho de Conclus\xe3o de Curso 1 (TCC 1)</b></a></li>\r\n		<li class="nav-item"><a class="nav-link" href="engenharia/tcc2.html"><b>Trabalho de Conclus\xe3o de Curso 2 (TCC 2)</b></a></li>\r\n            </ul>\r\n        </div>\r\n    </div>\r\n</nav>\r\n\r\n\r\nPREAMBULO_PAGINA\r\n\r\n# imprime lista dos grupos\r\n$dbStatement5->execute();\r\n\r\nprint <<PREAMBULO_LISTA_LIDERES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de professores ########## --\x3e \r\n<div class="title">Lista de grupos do DAELT</a></div>\r\n<div>\r\n\r\n<p>Abaixo segue a lista de grupos, e seus respectivos l\xedderes. Estes professores receber\xe3o as propostas de Metodologia Aplicada ao TCC e as distribuir\xe3o entre os membros de seus grupos para avalia\xe7\xe3o.</p>\r\n<table class="tabelas-professor">\r\n\r\n<tr>\r\n	<th>Grupo</th>\r\n	<th>L\xedder [C\xf3digo]</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_LIDERES\r\n\r\nwhile ( @dbLinha = $dbStatement5->fetchrow_array )\r\n{\r\n	# imprime grupos + l\xedder\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[0]</td>";\r\n	print "\\t<td>$dbLinha[2] [$dbLinha[1]]</td>";\r\n	print "</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_LIDERES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_LIDERES\r\n\r\n\r\n# imprime lista dos professores\r\n$dbStatement1->execute();\r\n\r\nprint <<PREAMBULO_LISTA_PROFESSORES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de professores ########## --\x3e \r\n<div class="title">Lista de professores do DAELT</a></div>\r\n<div>\r\n<p>Abaixo segue a lista de professores e o grupo a que pertence.</p>\r\n<table class="tabelas-professor">\r\n	<col width="50%" />\r\n	<col width="50%" />\r\n\r\n<tr>\r\n	<th>Professor [C\xf3digo]</th>\r\n	<th>Grupo</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_PROFESSORES\r\n\r\nwhile ( @dbLinha = $dbStatement1->fetchrow_array )\r\n{\r\n	my $professor_id_saved = $dbLinha[0];\r\n\r\n	# imprime nome + emails\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[1] [$dbLinha[0]]";\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[2]) . "</span>" if (defined $dbLinha[2]);\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[3]) . "</span>" if (defined $dbLinha[3]);\r\n	print "</td>$crlf";\r\n\r\n	# imprime grupos\r\n	$dbStatement2->bind_param(1, $professor_id_saved);\r\n	$dbStatement2->execute();\r\n\r\n	print "\\t<td>";\r\n	my $checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement2->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf";\r\n\r\n	# imprime interesses\r\n	#$dbStatement3->bind_param(1, $professor_id_saved);\r\n	#$dbStatement3->execute();\r\n\r\n	#print "\\t<td>";\r\n	#$checa_existencia = 0;\r\n	#while ( @dbLinha = $dbStatement3->fetchrow_array )\r\n	#{\r\n	#	print "<ul>$crlf" if $checa_existencia == 0;\r\n	#	$checa_existencia = 1;\r\n\r\n	#	print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	#}\r\n	#print "\\t</ul>" if $checa_existencia == 1;\r\n	#print "</td>$crlf";\r\n\r\n	# imprime temas\r\n	#$dbStatement4->bind_param(1, $professor_id_saved);\r\n	#$dbStatement4->execute();\r\n\r\n	#print "\\t<td>";\r\n	#$checa_existencia = 0;\r\n	#while ( @dbLinha = $dbStatement4->fetchrow_array )\r\n	#{\r\n	#	print "<ul>$crlf" if $checa_existencia == 0;\r\n	#	$checa_existencia = 1;\r\n\r\n	#	print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	#}\r\n	#print "\\t</ul>" if $checa_existencia == 1;\r\n	#print "</td>$crlf</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_PROFESSORES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_PROFESSORES\r\n\r\n\r\n# imprime lista dos professores\r\n$dbStatement6->execute();\r\n\r\nprint <<PREAMBULO_LISTA_VISITANTES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de visitantes ########## --\x3e \r\n<div class="title">Lista de visitantes/colaboradores do DAELT</a></div>\r\n<div>\r\n<p>Abaixo segue a lista de visitantes/colaboradores, suas \xe1reas de atua\xe7\xe3o, e o grupo do DAELT com o qual j\xe1 colaboraram.</p>\r\n<table class="tabelas-professor">\r\n	<col width="50%" />\r\n	<col width="50%" />\r\n\r\n<tr>\r\n	<th>Visitante [C\xf3digo]</th>\r\n	<th>Grupo</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_VISITANTES\r\n\r\nwhile ( @dbLinha = $dbStatement6->fetchrow_array )\r\n{\r\n	my $professor_id_saved = $dbLinha[0];\r\n\r\n	# imprime nome + emails\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[1] [$dbLinha[0]]";\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[2]) . "</span>" if (defined $dbLinha[2]);\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[3]) . "</span>" if (defined $dbLinha[3]);\r\n	print "</td>$crlf";\r\n\r\n	# imprime grupos\r\n	$dbStatement2->bind_param(1, $professor_id_saved);\r\n	$dbStatement2->execute();\r\n\r\n	print "\\t<td>";\r\n	my $checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement2->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_VISITANTES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_VISITANTES\r\n\r\n\r\n# impress\xe3o da peroracao (conforme p\xe1gina)\r\nprint <<PERORACAO;\r\n\x3c!-- ############# Nova bloco de informa\xe7\xf5es: Valida\xe7\xf5es HTML ############ --\x3e \r\n<div class="footer">\r\n    <a href="https://validator.w3.org/check?uri=referer">\r\n        <img src="https://www.w3.org/Icons/valid-xhtml10" alt="Valid XHTML 1.0 Transitional" height="31" width="88">\r\n    </a>\r\n    <a href="https://jigsaw.w3.org/css-validator/check/referer">\r\n        <img src="https://jigsaw.w3.org/css-validator/images/vcss" alt="CSS v\xe1lido!" height="31" width="88">\r\n    </a>\r\n</div>\r\n\r\n\r\n</body>\r\n</html>\r\nPERORACAO\r\n\r\n# desconex\xe3o com banco de dados\r\n$dbHandle->disconnect();\r\nexit 0;\r\n\r\n\r\n# -----------------------------------------------------------------------------\r\n# Embaralha email para evitar spam!\r\n# -----------------------------------------------------------------------------\r\nsub embaralha_email\r\n{\r\n	my $email = $_[0];\r\n\r\n	if ($email =~ /^([\\w\\.\\-\\_]+)\\@([\\w\\.\\-\\_]+[a-zA-Z]{2,})$/)\r\n	{\r\n		my $nome = $1;\r\n		my $host = $2;\r\n		$host =~ s/\\./ [dot] /g;\r\n		$email = $nome . " [at] " . $host;\r\n	}\r\n\r\n	return $email;\r\n}\n'})})]})}function p(r={}){let{wrapper:n}={...(0,s.R)(),...r.components};return n?(0,a.jsx)(n,{...r,children:(0,a.jsx)(l,{...r})}):l(r)}},28453(r,n,e){e.d(n,{R:()=>i,x:()=>o});var t=e(96540);let a={},s=t.createContext(a);function i(r){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof r?r(n):{...n,...r}},[n,r])}function o(r){let n;return n=r.disableParentContext?"function"==typeof r.components?r.components(a):r.components||a:i(r.components),t.createElement(s.Provider,{value:n},r.children)}}}]);